
import React, { useState, createContext, useContext, useEffect, useCallback } from 'react';
import { GlobalSettings, DEFAULT_RECEIPT_CONFIG, DEFAULT_PAYMENT_METHODS, DEFAULT_PAYMENT_METHOD_SCOPES } from '../types';
import { api } from '../services/api';

export interface GlobalSettingsContextType {
  settings: GlobalSettings;
  updateSettings: (newSettings: Partial<GlobalSettings>) => void;
  /** Carga la configuración del negocio desde la base de datos (llamar tras login). */
  loadSettings: () => Promise<void>;
  t: (key: string, params?: Record<string, string | number>) => string;
}

export const GlobalSettingsContext = createContext<GlobalSettingsContextType | null>(null);

const DEFAULT_SETTINGS: GlobalSettings = {
    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
    numberFormat: 'comma_decimal',
    language: 'es',
    fontSize: 'md',
    defaultTaxRate: 0.115, // Default IVU in PR is 11.5%
    receiptConfig: DEFAULT_RECEIPT_CONFIG,
    paymentMethods: DEFAULT_PAYMENT_METHODS,
    paymentMethodScopes: DEFAULT_PAYMENT_METHOD_SCOPES,
    enabledModules: {},
    loyaltyPointsPerDollar: 0,
    taxBreakdownEnabled: false,
    taxStateRate: 0.105,
    taxMunicipalRate: 0.01,
    taxReducedRate: 0.06,
};

